package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchResult struct {
	ID    int    `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
	Role  string `json:"role"`
}

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
	db.SetMaxOpenConns(10)
}

// validateInput performs basic input sanitization
func validateInput(input string) string {
	// Remove null bytes and trim whitespace
	input = strings.ReplaceAll(input, "\x00", "")
	input = strings.TrimSpace(input)
	// Limit length to prevent buffer issues
	if len(input) > 200 {
		input = input[:200]
	}
	return input
}

// searchUsers handles user directory search
func searchUsers(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "Method not allowed", 405)
		return
	}

	department := validateInput(r.URL.Query().Get("dept"))
	nameFilter := validateInput(r.URL.Query().Get("name"))

	if department == "" {
		http.Error(w, "department required", 400)
		return
	}

	// Build query - nameFilter is optional additional filter
	query := fmt.Sprintf(
		"SELECT id, name, email, role FROM directory WHERE department = '%s'",
		department,
	)

	if nameFilter != "" {
		query += fmt.Sprintf(" AND name ILIKE '%%%s%%'", nameFilter)
	}

	query += " ORDER BY name LIMIT 50"

	rows, err := db.Query(query)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var results []SearchResult
	for rows.Next() {
		var sr SearchResult
		if err := rows.Scan(&sr.ID, &sr.Name, &sr.Email, &sr.Role); err != nil {
			continue
		}
		results = append(results, sr)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(results)
}

// healthCheck for load balancer
func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(200)
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/search", searchUsers)
	http.HandleFunc("/health", healthCheck)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, nil))
}
